-- check: by customer (reserved / shipped / pending / remaining against reserves)
select c.name as customer, sum(b.reserved) reserved, sum(b.shipped) shipped, sum(b.pending) pending, sum(b.remaining) remaining
  from reserve_balances b join customers c on c.id = b.customer_id group by c.name
union all
select 'TOTAL', sum(reserved), sum(shipped), sum(pending), sum(remaining) from reserve_balances
order by 2 desc;
